    47     // Generic json type.
    48     struct json_t
    49     {
    50        virtual ~json_t() {}
    51
    52        using array_t = std::vector<json_t>;
    53        using object_t = std::map<std::string, json_t, std::less<>>;
    54        using null_t = std::nullptr_t;
    55        using val_t = std::variant<null_t, double, std::string, bool, array_t, object_t>;
    56        val_t data{};
    57
    58        /**
    59         * @brief Converts the JSON data to a string representation.
    60         * @return An `expected` containing a JSON string if successful, or an error context.
    61         */
    62        expected<std::string, error_ctx> dump() const { return write_json(data); }
    63
    64        /**
    65         * @brief Gets the value as the specified type.
    66         * @tparam T The type to get the value as.
    67         * @return Reference to the value of the specified type.
    68         */
    69        template <class T>
    70        [[nodiscard]] T& get()
    71        {
    72           return std::get<T>(data);
    73        }
    74
    75        template <class T>
    76        [[nodiscard]] const T& get() const
    77        {
    78           return std::get<T>(data);
    79        }
    80
    81        template <class T>
    82        [[nodiscard]] T* get_if() noexcept
    83        {
    84           return std::get_if<T>(&data);
    85        }
    86
    87        template <class T>
    88        [[nodiscard]] const T* get_if() const noexcept
    89        {
    90           return std::get_if<T>(&data);
    91        }
    92
    93        template <class T>
    94        [[nodiscard]] T as() const
    95        {
    96           // Prefer get becuase it returns a reference
    97           return get<T>();
    98        }
    99
   100        template <class T>
   101           requires(requires { static_cast<T>(std::declval<double>()); })
   102        [[nodiscard]] T as() const
   103        {
   104           // Can be used for int and the like
   105           return static_cast<T>(get<double>());
   106        }
   107
   108        template <class T>
   109           requires std::convertible_to<std::string, T>
   110        [[nodiscard]] T as() const
   111        {
   112           // Can be used for string_view and the like
   113           return get<std::string>();
   114        }
