   116        template <class T>
   117        [[nodiscard]] bool holds() const noexcept
   118        {
   119           return std::holds_alternative<T>(data);
   120        }
   121
   122        json_t& operator[](std::integral auto&& index) { return std::get<array_t>(data)[index]; }
   123
   124        const json_t& operator[](std::integral auto&& index) const { return std::get<array_t>(data)[index]; }
   125
   126        json_t& operator[](std::convertible_to<std::string_view> auto&& key)
   127        {
   128           //[] operator for maps does not support heterogeneous lookups yet
   129           if (holds<null_t>()) data = object_t{};
   130           auto& object = std::get<object_t>(data);
   131           auto iter = object.find(key);
   132           if (iter == object.end()) {
   133              iter = object.insert(std::make_pair(std::string(key), json_t{})).first;
   134           }
   135           return iter->second;
   136        }
   137
   138        const json_t& operator[](std::convertible_to<std::string_view> auto&& key) const
   139        {
   140           //[] operator for maps does not support heterogeneous lookups yet
   141           auto& object = std::get<object_t>(data);
   142           auto iter = object.find(key);
   143           if (iter == object.end()) {
   144              glaze_error("Key not found.");
   145           }
   146           return iter->second;
   147        }
   148
   149        json_t& operator=(const std::nullptr_t value)
   150        {
   151           data = value;
   152           return *this;
   153        }
   154
   155        json_t& operator=(const double value)
   156        {
   157           data = value;
   158           return *this;
   159        }
   160
   161        // for integers
   162        template <int_t T>
   163        json_t& operator=(const T value)
   164        {
   165           data = static_cast<double>(value);
   166           return *this;
   167        }
   168
   169        json_t& operator=(const std::string& value)
   170        {
   171           data = value;
   172           return *this;
   173        }
   174
   175        json_t& operator=(const std::string_view value)
   176        {
   177           data = std::string(value);
   178           return *this;
   179        }
   180
   181        json_t& operator=(const char* value)
   182        {
   183           data = std::string(value);
   184           return *this;
   185        }
   186
   187        json_t& operator=(const bool value)
   188        {
   189           data = value;
   190           return *this;
   191        }
   192
   193        json_t& operator=(const array_t& value)
   194        {
   195           data = value;
   196           return *this;
   197        }
   198
   199        json_t& operator=(const object_t& value)
   200        {
   201           data = value;
   202           return *this;
   203        }
   204
   205        [[nodiscard]] json_t& at(std::convertible_to<std::string_view> auto&& key) { return operator[](key); }
   206
   207        [[nodiscard]] const json_t& at(std::convertible_to<std::string_view> auto&& key) const { return operator[](key); }
   208
   209        [[nodiscard]] bool contains(std::convertible_to<std::string_view> auto&& key) const
   210        {
   211           if (!holds<object_t>()) return false;
   212           auto& object = std::get<object_t>(data);
   213           auto iter = object.find(key);
   214           return iter != object.end();
   215        }
   216
   217        explicit operator bool() const { return !std::holds_alternative<null_t>(data); }
   218
   219        val_t* operator->() noexcept { return &data; }
   220
   221        val_t& operator*() noexcept { return data; }
   222
   223        const val_t& operator*() const noexcept { return data; }
   224
   225        void reset() noexcept { data = null_t{}; }
   226
   227        json_t() = default;
   228        json_t(const json_t&) = default;
   229        json_t& operator=(const json_t&) = default;
   230        json_t(json_t&&) = default;
   231        json_t& operator=(json_t&&) = default;
   232
   233        template <class T>
   234           requires std::convertible_to<T, val_t> && (!std::derived_from<std::decay_t<T>, json_t>)
   235        json_t(T&& val)
   236        {
   237           data = val;
   238        }
   239
   240        template <class T>
   241           requires std::convertible_to<T, double> && (!std::derived_from<std::decay_t<T>, json_t>) &&
   242                    (!std::convertible_to<T, val_t>)
   243        json_t(T&& val)
   244        {
   245           data = static_cast<double>(val);
   246        }
   247
   248        json_t(const std::string_view value) { data = std::string(value); }
   249
   250        json_t(std::initializer_list<std::pair<const char*, json_t>>&& obj)
   251        {
   252           data.emplace<object_t>();
   253           auto& data_obj = std::get<object_t>(data);
   254           for (auto&& pair : obj) {
   255              // std::initializer_list holds const values that cannot be moved
   256              data_obj.emplace(pair.first, pair.second);
   257           }
   258        }
   259
   260        // Prevent conflict with object initializer list
   261        template <bool deprioritize = true>
   262        json_t(std::initializer_list<json_t>&& arr)
   263        {
   264           data.emplace<array_t>(std::move(arr));
   265        }
   266
   267        [[nodiscard]] bool is_array() const noexcept { return holds<json_t::array_t>(); }
   268
   269        [[nodiscard]] bool is_object() const noexcept { return holds<json_t::object_t>(); }
   270
   271        [[nodiscard]] bool is_number() const noexcept { return holds<double>(); }
   272
   273        [[nodiscard]] bool is_string() const noexcept { return holds<std::string>(); }
   274
   275        [[nodiscard]] bool is_boolean() const noexcept { return holds<bool>(); }
   276
   277        [[nodiscard]] bool is_null() const noexcept { return holds<std::nullptr_t>(); }
   278
   279        [[nodiscard]] array_t& get_array() { return get<array_t>(); }
   280        [[nodiscard]] const array_t& get_array() const { return get<array_t>(); }
   281
   282        [[nodiscard]] object_t& get_object() { return get<object_t>(); }
   283        [[nodiscard]] const object_t& get_object() const { return get<object_t>(); }
   284
   285        [[nodiscard]] double& get_number() { return get<double>(); }
   286        [[nodiscard]] const double& get_number() const { return get<double>(); }
   287
   288        [[nodiscard]] std::string& get_string() { return get<std::string>(); }
   289        [[nodiscard]] const std::string& get_string() const { return get<std::string>(); }
   290
   291        [[nodiscard]] bool& get_boolean() { return get<bool>(); }
   292        [[nodiscard]] const bool& get_boolean() const { return get<bool>(); }
   293
   294        // empty() returns true if the value is an empty JSON object, array, or string, or a null value
   295        // otherwise returns false
   296        [[nodiscard]] bool empty() const noexcept
   297        {
   298           if (auto* v = get_if<object_t>()) {
   299              return v->empty();
   300           }
   301           else if (auto* v = get_if<array_t>()) {
   302              return v->empty();
   303           }
   304           else if (auto* v = get_if<std::string>()) {
   305              return v->empty();
   306           }
   307           else if (is_null()) {
   308              return true;
   309           }
   310           else {
   311              return false;
   312           }
   313        }
   314
   315        // returns the count of items in an object or an array, or the size of a string, otherwise returns zero
   316        [[nodiscard]] size_t size() const noexcept
   317        {
   318           if (auto* v = get_if<object_t>()) {
   319              return v->size();
   320           }
   321           else if (auto* v = get_if<array_t>()) {
   322              return v->size();
   323           }
   324           else if (auto* v = get_if<std::string>()) {
   325              return v->size();
   326           }
   327           else {
   328              return 0;
   329           }
   330        }
   331     };
