   333     [[nodiscard]] inline bool is_array(const json_t& value) noexcept { return value.is_array(); }
   334
   335     [[nodiscard]] inline bool is_object(const json_t& value) noexcept { return value.is_object(); }
   336
   337     [[nodiscard]] inline bool is_number(const json_t& value) noexcept { return value.is_number(); }
   338
   339     [[nodiscard]] inline bool is_string(const json_t& value) noexcept { return value.is_string(); }
   340
   341     [[nodiscard]] inline bool is_boolean(const json_t& value) noexcept { return value.is_boolean(); }
   342
   343     [[nodiscard]] inline bool is_null(const json_t& value) noexcept { return value.is_null(); }
   344  }
