   356     // These functions allow a json_t value to be read/written to a C++ struct
   357
   358     template <auto Opts, class T>
   359        requires read_supported<T, Opts.format>
   360     [[nodiscard]] error_ctx read(T& value, const json_t& source)
   361     {
   362        auto buffer = source.dump();
   363        if (buffer) {
   364           context ctx{};
   365           return read<Opts>(value, *buffer, ctx);
   366        }
   367        else {
   368           return buffer.error();
   369        }
   370     }
