   406     // Specialization for glz::json_t
   407     template <>
   408     struct seek_op<glz::json_t>
   409     {
   410        template <class F>
   411        static bool op(F&& func, auto&& value, sv json_ptr)
   412        {
   413           if (json_ptr.empty()) {
   414              // At target - call func with the actual variant data, not the json_t wrapper
   415              std::visit([&func](auto&& variant_value) { func(variant_value); }, value.data);
   416              return true;
   417           }
   418
   419           if (json_ptr[0] != '/' || json_ptr.size() < 2) return false;
   420
   421           // Handle object access
   422           if (value.is_object()) {
   423              auto& obj = value.get_object();
   424
   425              // Parse the key (with JSON Pointer escaping)
   426              std::string key;
   427              size_t i = 1;
   428              for (; i < json_ptr.size(); ++i) {
   429                 auto c = json_ptr[i];
   430                 if (c == '/')
   431                    break;
   432                 else if (c == '~') {
   433                    if (++i == json_ptr.size()) return false;
   434                    c = json_ptr[i];
   435                    if (c == '0')
   436                       c = '~';
   437                    else if (c == '1')
   438                       c = '/';
   439                    else
   440                       return false;
   441                 }
   442                 key.push_back(c);
   443              }
   444
   445              auto it = obj.find(key);
   446              if (it == obj.end()) return false;
   447
   448              sv remaining_ptr = json_ptr.substr(i);
   449              return seek(std::forward<F>(func), it->second, remaining_ptr);
   450           }
   451           // Handle array access
   452           else if (value.is_array()) {
   453              auto& arr = value.get_array();
   454
   455              // Parse the index
   456              size_t index{};
   457              auto [p, ec] = std::from_chars(&json_ptr[1], json_ptr.data() + json_ptr.size(), index);
   458              if (ec != std::errc{}) return false;
   459
   460              if (index >= arr.size()) return false;
   461
   462              sv remaining_ptr = json_ptr.substr(p - json_ptr.data());
   463              return seek(std::forward<F>(func), arr[index], remaining_ptr);
   464           }
   465
   466           return false;
   467        }
   468     };
   469  }
