    12  // Use JSON Pointer syntax to seek to a specific element
    13  // https://github.com/stephenberry/JSON-Pointer
    14
    15  namespace glz
    16  {
    17     template <class T>
    18     struct seek_op;
    19
    20     // Call a function on an value at the location of a json_ptr
    21     template <class F, class T>
    22     bool seek(F&& func, T&& value, sv json_ptr)
    23     {
    24        return seek_op<std::remove_cvref_t<T>>::op(std::forward<F>(func), std::forward<T>(value), json_ptr);
    25     }
    26
    27     // Default implementation for types that don't have specific specializations
    28     template <class T>
    29     struct seek_op
    30     {
    31        template <class F>
    32        static bool op(F&& func, auto&& value, sv json_ptr)
    33        {
    34           if (json_ptr.empty()) {
    35              func(value);
    36              return true;
    37           }
    38           return false;
    39        }
    40     };
