    42     // Specialization for glaze_value_t types
    43     template <class T>
    44        requires glaze_value_t<T>
    45     struct seek_op<T>
    46     {
    47        template <class F>
    48        static bool op(F&& func, auto&& value, sv json_ptr)
    49        {
    50           decltype(auto) member = get_member(value, meta_wrapper_v<T>);
    51           if (json_ptr.empty()) {
    52              func(member);
    53              return true;
    54           }
    55           return seek(std::forward<F>(func), member, json_ptr);
    56        }
    57     };
