    59     // Specialization for array-like types
    60     template <class T>
    61        requires(glaze_array_t<T> || tuple_t<T> || array_t<T> || is_std_tuple<T>)
    62     struct seek_op<T>
    63     {
    64        template <class F>
    65        static bool op(F&& func, auto&& value, sv json_ptr)
    66        {
    67           if (json_ptr.empty()) {
    68              func(value);
    69              return true;
    70           }
    71           if (json_ptr[0] != '/' || json_ptr.size() < 2) return false;
    72
    73           size_t index{};
    74           auto [p, ec] = std::from_chars(&json_ptr[1], json_ptr.data() + json_ptr.size(), index);
    75           if (ec != std::errc{}) return false;
    76           json_ptr = json_ptr.substr(p - json_ptr.data());
    77
    78           if constexpr (glaze_array_t<T>) {
    79              static constexpr auto member_array = glz::detail::make_array<T>();
    80              if (index >= member_array.size()) return false;
    81              return std::visit(
    82                 [&](auto&& element) { return seek(std::forward<F>(func), get_member(value, element), json_ptr); },
    83                 member_array[index]);
    84           }
    85           else if constexpr (tuple_t<T> || is_std_tuple<T>) {
    86              if (index >= glz::tuple_size_v<T>) return false;
    87              auto tuple_element_ptr = detail::get_runtime(value, index);
    88              return std::visit([&](auto&& element_ptr) { return seek(std::forward<F>(func), *element_ptr, json_ptr); },
    89                                tuple_element_ptr);
    90           }
    91           else {
    92              return seek(std::forward<F>(func), *std::next(value.begin(), index), json_ptr);
    93           }
    94        }
    95     };
