    97     // Specialization for nullable types
    98     template <class T>
    99        requires nullable_t<T>
   100     struct seek_op<T>
   101     {
   102        template <class F>
   103        static bool op(F&& func, auto&& value, sv json_ptr)
   104        {
   105           if (json_ptr.empty()) {
   106              func(value);
   107              return true;
   108           }
   109           if (!value) return false;
   110           return seek(std::forward<F>(func), *value, json_ptr);
   111        }
