   114     // Specialization for object/map types
   115     template <class T>
   116        requires(readable_map_t<T> || glaze_object_t<T> || reflectable<T>)
   117     struct seek_op<T>
   118     {
   119        template <class F>
   120        static bool op(F&& func, auto&& value, sv json_ptr)
   121        {
   122           if (json_ptr.empty()) {
   123              func(value);
   124              return true;
   125           }
   126           if (json_ptr[0] != '/' || json_ptr.size() < 2) return false;
   127
   128           static thread_local auto key = []() {
   129              if constexpr (writable_map_t<T>) {
   130                 return typename T::key_type{};
   131              }
   132              else {
   133                 return std::string{};
   134              }
   135           }();
   136           using Key = std::decay_t<decltype(key)>;
   137           static_assert(std::is_same_v<Key, std::string> || num_t<Key>);
   138
   139           if constexpr (std::is_same_v<Key, std::string>) {
   140              key.clear();
   141              size_t i = 1;
   142              for (; i < json_ptr.size(); ++i) {
   143                 auto c = json_ptr[i];
   144                 if (c == '/')
   145                    break;
   146                 else if (c == '~') {
   147                    if (++i == json_ptr.size()) return false;
   148                    c = json_ptr[i];
   149                    if (c == '0')
   150                       c = '~';
   151                    else if (c == '1')
   152                       c = '/';
   153                    else
   154                       return false;
   155                 }
   156                 key.push_back(c);
   157              }
   158              json_ptr = json_ptr.substr(i);
   159           }
   160           else if constexpr (std::floating_point<Key>) {
   161              auto [ptr, ec] = glz::from_chars<false>(json_ptr.data(), json_ptr.data() + json_ptr.size(), key);
   162              if (ec != std::errc()) [[unlikely]] {
   163                 return false;
   164              }
   165              json_ptr = json_ptr.substr(size_t(ptr - json_ptr.data()));
   166           }
   167           else {
   168              auto [p, ec] = std::from_chars(&json_ptr[1], json_ptr.data() + json_ptr.size(), key);
   169              if (ec != std::errc{}) return false;
   170              json_ptr = json_ptr.substr(p - json_ptr.data());
   171           }
   172
   173           if constexpr (glaze_object_t<T> || reflectable<T>) {
   174              static constexpr auto N = reflect<T>::size;
   175              static constexpr auto HashInfo = hash_info<T>;
   176              static_assert(HashInfo.type != hash_type::invalid, "Hashing failed");
   177
   178              const auto index = decode_hash_with_size<JSON_PTR, T, HashInfo, HashInfo.type>::op(
   179                 key.data(), key.data() + key.size(), key.size());
   180
